"use client";

import * as React from "react";
import { AnimatePresence, MotionConfig, motion, useMotionValueEvent } from "motion/react";
import { cn } from "@/lib/utils";
import {
  EASE,
  Logo,
  MenuGlyph,
  accentVars,
  preventPlaceholder,
  ring,
  surface,
  useDismiss,
  useScrollY,
} from "@/components/prestigeui/navbar-ui";

type NavLink = { label: string; href: string };

type NavbarCondenseProps = {
  brand?: string;
  links?: NavLink[];
  activeHref?: string;
  signInHref?: string;
  ctaLabel?: string;
  ctaHref?: string;
  className?: string;
};

const defaultLinks: NavLink[] = [
  { label: "Product", href: "#product" },
  { label: "Customers", href: "#customers" },
  { label: "Changelog", href: "#changelog" },
  { label: "Pricing", href: "#pricing" },
];

// Hysteresis: condense after 40px, expand again only near the very top, so
// a pointer resting on the threshold never makes the bar flicker.
const CONDENSE_AT = 40;
const EXPAND_AT = 8;

function NavbarCondense({
  brand = "Prestige UI",
  links = defaultLinks,
  activeHref,
  signInHref = "#",
  ctaLabel = "Get started",
  ctaHref = "#",
  className,
}: NavbarCondenseProps) {
  const headerRef = React.useRef<HTMLElement>(null);
  const panelRef = React.useRef<HTMLDivElement>(null);
  const toggleRef = React.useRef<HTMLButtonElement>(null);
  const { y } = useScrollY(headerRef);
  const [condensed, setCondensed] = React.useState(false);
  const [open, setOpen] = React.useState(false);
  const [active, setActive] = React.useState(activeHref);
  const panelId = React.useId();

  useMotionValueEvent(y, "change", (value) => {
    if (!condensed && value > CONDENSE_AT) setCondensed(true);
    else if (condensed && value < EXPAND_AT) setCondensed(false);
  });

  useDismiss(open, () => setOpen(false), [panelRef, toggleRef], toggleRef);

  const go = (event: React.MouseEvent<HTMLAnchorElement>, href: string) => {
    preventPlaceholder(event);
    setActive(href);
    setOpen(false);
  };

  return (
    <MotionConfig reducedMotion="user">
      <header
        ref={headerRef}
        className={cn("sticky top-0 z-50 w-full px-3 font-sans text-foreground sm:px-4", accentVars, className)}
      >
        <div
          className={cn(
            "relative mx-auto flex h-14 items-center justify-between gap-4 border transition-[max-width,transform,padding,border-radius,background-color,border-color,box-shadow] duration-500 ease-[cubic-bezier(0.16,1,0.3,1)]",
            condensed || open
              ? "translate-y-3 max-w-[760px] rounded-2xl border-border bg-background/75 pr-2 pl-4 shadow-[0_1px_2px_rgba(0,0,0,0.04),0_12px_32px_-16px_rgba(15,23,42,0.25)] backdrop-blur-xl dark:shadow-[0_12px_32px_-16px_rgba(0,0,0,0.8)]"
              : "translate-y-1 max-w-6xl rounded-none border-transparent bg-transparent px-1 shadow-none",
          )}
        >
          <Logo name={brand} />

          <nav aria-label="Main" className="hidden items-center gap-0.5 md:flex">
            {links.map((link) => {
              const current = active === link.href;
              return (
                <a
                  key={link.label}
                  href={link.href}
                  aria-current={current ? "page" : undefined}
                  onClick={(event) => go(event, link.href)}
                  className={cn(
                    "rounded-lg px-3 py-1.5 text-[13.5px] font-medium transition-colors duration-200 hover:bg-foreground/[0.05] hover:text-foreground",
                    current ? "text-foreground" : "text-foreground/60",
                    ring,
                  )}
                >
                  {link.label}
                </a>
              );
            })}
          </nav>

          <div className="flex items-center gap-1.5">
            <a
              href={signInHref}
              onClick={preventPlaceholder}
              className={cn(
                "hidden h-9 items-center rounded-lg px-3 text-[13.5px] font-medium text-foreground/70 transition-colors duration-200 hover:text-foreground sm:inline-flex",
                ring,
              )}
            >
              Log in
            </a>
            <a
              href={ctaHref}
              onClick={preventPlaceholder}
              className={cn(
                "inline-flex h-9 items-center rounded-lg bg-foreground px-3.5 text-[13.5px] font-medium text-background shadow-[inset_0_1px_0_rgba(255,255,255,0.12)] transition-[transform,opacity] duration-150 hover:opacity-90 active:scale-[0.97]",
                ring,
              )}
            >
              {ctaLabel}
            </a>
            <button
              ref={toggleRef}
              type="button"
              aria-label={open ? "Close menu" : "Open menu"}
              aria-expanded={open}
              aria-controls={panelId}
              onClick={() => setOpen((value) => !value)}
              className={cn(
                "grid size-9 cursor-pointer place-items-center rounded-lg text-foreground/80 transition-colors duration-200 hover:bg-foreground/[0.05] md:hidden",
                ring,
              )}
            >
              <MenuGlyph open={open} />
            </button>
          </div>

          <AnimatePresence>
            {open ? (
              <motion.div
                ref={panelRef}
                id={panelId}
                initial={{ opacity: 0, y: -6 }}
                animate={{ opacity: 1, y: 0, transition: { duration: 0.28, ease: EASE } }}
                exit={{ opacity: 0, y: -4, transition: { duration: 0.15, ease: "easeOut" } }}
                className={cn("absolute inset-x-0 top-full mt-2 rounded-2xl p-2 md:hidden", surface)}
              >
                <nav aria-label="Mobile">
                  {links.map((link, index) => (
                    <motion.a
                      key={link.label}
                      href={link.href}
                      aria-current={active === link.href ? "page" : undefined}
                      onClick={(event) => go(event, link.href)}
                      initial={{ opacity: 0, y: -4 }}
                      animate={{ opacity: 1, y: 0, transition: { duration: 0.3, delay: 0.04 + index * 0.035, ease: EASE } }}
                      className={cn(
                        "flex h-11 items-center rounded-lg px-3 text-[15px] font-medium transition-colors hover:bg-foreground/[0.05]",
                        active === link.href ? "text-foreground" : "text-foreground/75",
                        ring,
                      )}
                    >
                      {link.label}
                    </motion.a>
                  ))}
                </nav>
                <div className="mt-2 border-t border-border px-1 pt-3 pb-1">
                  <a
                    href={signInHref}
                    onClick={preventPlaceholder}
                    className={cn(
                      "flex h-10 items-center justify-center rounded-lg border border-border text-[14px] font-medium",
                      ring,
                    )}
                  >
                    Log in
                  </a>
                </div>
              </motion.div>
            ) : null}
          </AnimatePresence>
        </div>
      </header>
    </MotionConfig>
  );
}

export { NavbarCondense, type NavbarCondenseProps };

"use client";

import * as React from "react";
import { AnimatePresence, motion, useMotionValue } from "motion/react";
import { cn } from "@/lib/utils";
import { BrandMark } from "@/components/prestigeui/prestige-brand";

export { BrandMark };

/** Strong ease-out: responds at once, lands softly. */
export const EASE = [0.16, 1, 0.3, 1] as const;

/**
 * One accent for meaning only (unread dots, progress, selection). Retint by
 * overriding --nav-accent on the header.
 */
export const accentVars = "[--nav-accent:#2f6bff] dark:[--nav-accent:#5b8bff]";

/** The focus ring every control in the family shares. */
export const ring =
  "outline-none focus-visible:ring-2 focus-visible:ring-[color-mix(in_oklab,var(--nav-accent)_45%,transparent)] focus-visible:ring-offset-1 focus-visible:ring-offset-background";

/** Floating surfaces: hairline border plus a soft, layered shadow. */
export const surface =
  "border border-border bg-background shadow-[0_1px_2px_rgba(0,0,0,0.04),0_12px_32px_-12px_rgba(15,23,42,0.22)] dark:shadow-[0_1px_2px_rgba(0,0,0,0.4),0_16px_40px_-12px_rgba(0,0,0,0.7)]";

// Placeholder links ("#") stay put instead of jumping or changing the URL.
// Real hrefs passed in by you navigate as usual.
export const preventPlaceholder = (event: React.MouseEvent<HTMLAnchorElement>) => {
  if (event.currentTarget.getAttribute("href") === "#") event.preventDefault();
};

/** The brand mark plus wordmark, shared by every navbar. */
export function Logo({
  name = "Prestige UI",
  href = "#",
  className,
  hideName = false,
}: {
  name?: string;
  href?: string;
  className?: string;
  hideName?: boolean;
}) {
  return (
    <a
      href={href}
      onClick={preventPlaceholder}
      aria-label={hideName ? name : undefined}
      className={cn(
        "inline-flex shrink-0 items-center gap-2 rounded-md text-[15px] font-semibold tracking-[-0.02em]",
        ring,
        className,
      )}
    >
      <BrandMark className="size-7" />
      {hideName ? null : name}
    </a>
  );
}

export function Kbd({ children, className }: { children: React.ReactNode; className?: string }) {
  return (
    <kbd
      className={cn(
        "inline-grid h-5 min-w-5 place-items-center rounded-[5px] border border-border bg-muted/60 px-1 font-sans text-[11px] font-medium text-muted-foreground",
        className,
      )}
    >
      {children}
    </kbd>
  );
}

const subscribeNothing = () => () => {};

/** True on Apple platforms, so shortcuts read ⌘ there and Ctrl elsewhere. */
export function useIsMac() {
  return React.useSyncExternalStore(
    subscribeNothing,
    () => /Mac|iPhone|iPad/.test(navigator.platform || navigator.userAgent),
    () => true,
  );
}

function scrollParent(node: HTMLElement | null): HTMLElement | Window {
  let el = node?.parentElement ?? null;
  while (el && el !== document.body) {
    if (/(auto|scroll|overlay)/.test(getComputedStyle(el).overflowY)) return el;
    el = el.parentElement;
  }
  return window;
}

/**
 * Scroll position of whatever actually scrolls this header: the window, or
 * the nearest scrolling ancestor (a preview pane, an app shell). Returns
 * a motion value so reading it never re-renders the tree.
 */
export function useScrollY(ref: React.RefObject<HTMLElement | null>) {
  const y = useMotionValue(0);

  React.useEffect(() => {
    const source = scrollParent(ref.current);
    const read = () => {
      const top = source === window ? window.scrollY : (source as HTMLElement).scrollTop;
      y.set(Math.max(0, top));
    };
    read();
    source.addEventListener("scroll", read, { passive: true });
    return () => {
      source.removeEventListener("scroll", read);
    };
  }, [ref, y]);

  return { y };
}

/**
 * Closes a popover on Escape (returning focus to its trigger) or on a
 * pointer press outside every element in `refs`.
 */
export function useDismiss(
  open: boolean,
  close: () => void,
  refs: React.RefObject<HTMLElement | null>[],
  trigger?: React.RefObject<HTMLElement | null>,
) {
  const closeRef = React.useRef(close);
  React.useEffect(() => {
    closeRef.current = close;
  });

  React.useEffect(() => {
    if (!open) return;
    const onPointer = (event: PointerEvent) => {
      const target = event.target as Node;
      if (refs.some((ref) => ref.current?.contains(target))) return;
      closeRef.current();
    };
    const onKey = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      closeRef.current();
      trigger?.current?.focus();
    };
    document.addEventListener("pointerdown", onPointer);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("pointerdown", onPointer);
      document.removeEventListener("keydown", onKey);
    };
    // refs are stable ref objects
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);
}

/** Arrow keys, Home and End move focus between a menu's items. */
export function onMenuKeyDown(event: React.KeyboardEvent<HTMLElement>) {
  const items = Array.from(
    event.currentTarget.querySelectorAll<HTMLElement>('[role="menuitem"],[role="menuitemradio"]'),
  );
  if (!items.length) return;
  const index = items.indexOf(document.activeElement as HTMLElement);
  let next = -1;
  if (event.key === "ArrowDown") next = (index + 1) % items.length;
  else if (event.key === "ArrowUp") next = (index - 1 + items.length) % items.length;
  else if (event.key === "Home") next = 0;
  else if (event.key === "End") next = items.length - 1;
  if (next < 0) return;
  event.preventDefault();
  items[next].focus();
}

/** Focuses the first item of a menu once it has mounted. */
export function focusFirstItem(menu: React.RefObject<HTMLElement | null>) {
  requestAnimationFrame(() =>
    menu.current
      ?.querySelector<HTMLElement>('[role="menuitem"],[role="menuitemradio"],input')
      ?.focus(),
  );
}

/**
 * A floating panel anchored under its trigger. It grows from the trigger's
 * side, enters with ease-out and leaves faster than it came.
 */
export function Popover({
  open,
  align = "start",
  className,
  children,
  ...rest
}: {
  open: boolean;
  align?: "start" | "end" | "center";
  className?: string;
  children: React.ReactNode;
  ref?: React.Ref<HTMLDivElement>;
} & Omit<React.HTMLAttributes<HTMLDivElement>, "onAnimationStart" | "onDrag" | "onDragStart" | "onDragEnd">) {
  const origin = align === "end" ? "top right" : align === "center" ? "top center" : "top left";
  return (
    <AnimatePresence>
      {open ? (
        <motion.div
          {...rest}
          initial={{ opacity: 0, y: -4, scale: 0.97 }}
          animate={{ opacity: 1, y: 0, scale: 1, transition: { duration: 0.22, ease: EASE } }}
          exit={{ opacity: 0, y: -2, scale: 0.98, transition: { duration: 0.12, ease: "easeOut" } }}
          style={{ transformOrigin: origin }}
          className={cn(
            "absolute top-full z-50 mt-2 rounded-xl p-1",
            surface,
            align === "end" ? "right-0" : align === "center" ? "left-1/2 -translate-x-1/2" : "left-0",
            className,
          )}
        >
          {children}
        </motion.div>
      ) : null}
    </AnimatePresence>
  );
}

/** Two lines that fold into an X. Pure transform, no icon swap flicker. */
export function MenuGlyph({ open }: { open: boolean }) {
  return (
    <span aria-hidden className="relative block h-3 w-4">
      <span
        className={cn(
          "absolute top-[5px] left-0 h-[1.5px] w-4 rounded-full bg-current transition-transform duration-300 ease-[cubic-bezier(0.16,1,0.3,1)]",
          open ? "rotate-45" : "-translate-y-[3px]",
        )}
      />
      <span
        className={cn(
          "absolute top-[5px] left-0 h-[1.5px] w-4 rounded-full bg-current transition-transform duration-300 ease-[cubic-bezier(0.16,1,0.3,1)]",
          open ? "-rotate-45" : "translate-y-[3px]",
        )}
      />
    </span>
  );
}

import { cn } from "@/lib/utils";

/**
 * The Prestige UI mark: a hexagonal P ribbon around a small shaded cube,
 * drawn inline so it needs no image files. Ink in light mode, slate in dark;
 * `tone="ink"` keeps the ink colors for marks that sit on white in any theme.
 */
function BrandMark({ className, tone = "auto" }: { className?: string; tone?: "auto" | "ink" }) {
  const dark = tone === "auto";
  return (
    <svg viewBox="245 214 764 764" className={cn("size-6 shrink-0", className)} aria-hidden>
      <path
        d="M626 222 961 414V772L622 975 519 917V780L628 835 838 712V481L628 357 413 481V866L292 798V414Z"
        strokeWidth="14"
        strokeLinejoin="round"
        className={cn("fill-[#1b1d23] stroke-[#1b1d23]", dark && "dark:fill-[#8fa2c3] dark:stroke-[#8fa2c3]")}
      />
      <path d="M627 478 734 539 627 600 520 539Z" className={cn("fill-[#9497a3]", dark && "dark:fill-[#e6e8f8]")} />
      <path d="M520 539 627 600V720L520 659Z" className={cn("fill-[#565865]", dark && "dark:fill-[#bcc0e0]")} />
      <path d="M627 600 734 539V659L627 720Z" className={cn("fill-[#2c2e36]", dark && "dark:fill-[#a5a8c7]")} />
    </svg>
  );
}

export { BrandMark };
